    "name": "HO-WS-021",
    "branch": "Harbor Office",
    "seen": "2026-03-10T09:57:00Z"
  },
  {
    "name": "CC-WS-003",
    "branch": "Central Campus",
    "seen": null
  },
  {
    "name": "CC-SRV-APP",
    "branch": "Central Campus",
    "seen": "2026-03-10T09:59:30Z"
  }
];
type Port = (typeof ports)[number];
const styles = {
  "Online": "border-solid bg-emerald-100 text-emerald-950",
  "Stale": "border-solid border-amber-700",
  "Never seen": "border-dashed"
};
const icons = {
  "Online": "✓",
  "Stale": "◷",
  "Never seen": "−"
};
function state(port: Port) {
  if (!port.seen) return 'Never seen';
  return Date.parse('2026-03-10T10:00:00Z') - Date.parse(port.seen) > 15 * 60000 ? 'Stale' : 'Online';
}

export default function PatchPanelStrip() {
  const [current, inspect] = useState(ports[0]);
  const groups = [...new Set(ports.map(p => p.branch))];
  return <section className="grid min-w-0 gap-3 p-3 text-start text-sm" aria-label="Endpoint patch panel">
    <div className="grid grid-cols-1 gap-3 sm:grid-cols-3">{groups.map(group => <div key={group}>
      <h3 className="mb-2 font-semibold">{group}</h3>
      <div className="grid grid-flow-col grid-rows-2 gap-1">{ports.filter(p => p.branch === group).map(p =>
        <button type="button" key={p.name} className="flex flex-wrap items-center justify-between gap-2 rounded-sm border px-2 py-2 text-start font-mono text-xs aria-pressed:outline-2 focus-visible:outline-2" aria-pressed={current.name === p.name}
          title={'Last check-in: ' + (p.seen || 'Never seen')} onClick={() => inspect(p)}>
          <span>{p.name}</span><span className={'inline-flex items-center gap-1 rounded-sm border px-1.5 py-0.5 ' + styles[state(p)]}>
            <span aria-hidden="true">{icons[state(p)]}</span>{state(p)}
          </span>
        </button>)}</div>
    </div>)}</div>
    <output className="block border-s-2 ps-3">{current.name} · {state(current)} · Last check-in: {current.seen || 'Never seen'}</output>
  </section>;
}
